env = Environment(loader=FileSystemLoader(os.path.abspath('.')))
template = env.get_template('compris-demo.html')
output_from_parsed_template = template.render(response = response)
with open("compris-demo-copy.html", "w") as fh:
    fh.write(output_from_parsed_template)

_HTML = os.path.dirname(os.path.realpath(__file__)) + "/" + "compris-demo-copy.html"
_OUTFILE = "output.pdf"
sourcepath = 'file://' + _HTML


async def generate_pdf():
    browser = await launch()
    page = await browser.newPage()
    await page.goto(sourcepath, {'waitUntil': 'networkidle2'})
    await page.pdf({
      'path': _OUTFILE,
      'format': 'A5',
      'printBackground': True,
      'margin': {
        'top': 0,
        'bottom': 0,
        'left': 0,
        'right': 0
      }
    })
    await browser.close()


